mapper.update:

		UPDATE KEPRQDT /*saveAllRQDT*/
	      SET ATOB_UNIT_PRICE=0,        
               MAKER_NAME=#{MAKER_NAME},
               ORIGIN_NAME=(SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE=#{ORIGIN_CODE}), 
               IMAGE_KEY=#{SELLER_IMAGE_KEY},
               ORIGIN_CODE=#{ORIGIN_CODE},
               MAKER_CODE=#{MAKER_CODE},
               PROCESS_TYPE=#{PROCESS_TYPE},
               IMPORT_FLAG=#{IMPORT_FLAG},
               WAREHOUSE_CODE=#{WAREHOUSE_CODE},
               BELOW_COMORG_CODE=#{BELOW_COMORG_CODE} 
               , ATOS_REMARK = #{st_atos_remark}
               , KEP_RATE = NVL(#{RATE},0)
               , IMGFILE_DIR =#{IMGFILE_DIR}
               , IMGFILE_NAME =#{IMGFILE_NAME}
               , RFQ_IMG_TYPE =#{RFQ_IMG_TYPE}
               , TAX_TYPE = DECODE(#{TAX_TYPE}, '', '11', #{TAX_TYPE})
               , ITEM_MAKE_TYPE = #{ITEM_MAKE_TYPE}
               , PRE_GR_USER_NAME = #{AGENT_CHOICE_REQ_DEPT}
               , PRE_GR_DEPT_NAME = #{AGENT_CHOICE_REQ_USER}
	     WHERE BUYER         = #{st_buyer_code}
	       AND QUOTATION_NO  = #{st_quotation_no}
	       AND QUOTATION_SEQ = #{QUOTATION_SEQ}
	       AND REVISION      = #{st_revision}
	       AND STATUS <> 'D'


	UPDATE KEPQTDT /*saveAllQTDT*/
       SET ATOB_UNIT_PRICE = #{ATOB_UNIT_PRICE}
          , BID_SUCCESS_FLAG   = DECODE(#{AGENT_CHECK},'1','Y','N')
          , BID_SUCCESS_CODE   = DECODE(#{AGENT_CHECK},'1',#{BID_CODE},'')
          , BID_SUCCESS_REASON = DECODE(#{AGENT_CHECK},'1',#{BID_REMARK},'')
          , BID_SUCCESS_KEP= DECODE(#{AGENT_CHECK},'1',#{USER_ID},'')
          , BID_SUCCESS_DATM = DECODE(#{AGENT_CHECK},'1',SYSDATE,'')
          , MIN_ORDER_QTY = DECODE(#{MIN_ORDER_QTY}, '', 1, #{MIN_ORDER_QTY})
          , PUR_UNIT_QTY = DECODE(#{PUR_UNIT_QTY}, '', 1, #{PUR_UNIT_QTY})
          , SELLER_AREA = #{SELLER_AREA}
          , AGENT_CHOICE_SEQ = DECODE(#{AGENT_CHECK},'1',#{AGENT_CHOICE_SEQ},'')
     WHERE BUYER = #{st_buyer_code}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{QUOTATION_SEQ}
       AND REVISION = #{st_revision}
       AND AGENT = #{AGENT}
       AND AGENT_REVISION = #{AGENT_REVISION}
       AND STATUS <> 'D'


	UPDATE KEPQTDT /*saveAllSoQTDT*/
       SET BID_SUCCESS_FLAG   = DECODE(#{AGENT_CHECK},'1','Y','N')
          , BID_SUCCESS_CODE   = DECODE(#{AGENT_CHECK},'1',#{BID_CODE},'')
          , BID_SUCCESS_REASON = DECODE(#{AGENT_CHECK},'1',#{BID_REMARK},'')
          , BID_SUCCESS_KEP= DECODE(#{AGENT_CHECK},'1',#{USER_ID},'')
          , BID_SUCCESS_DATM = DECODE(#{AGENT_CHECK},'1',SYSDATE,'')
          , MIN_ORDER_QTY = DECODE(#{MIN_ORDER_QTY}, '', 1, #{MIN_ORDER_QTY})
          , PUR_UNIT_QTY = DECODE(#{PUR_UNIT_QTY}, '', 1, #{PUR_UNIT_QTY})
          , SELLER_AREA = #{SELLER_AREA}
          , AGENT_CHOICE_SEQ = DECODE(#{AGENT_CHECK},'1',#{AGENT_CHOICE_SEQ},'')
     WHERE BUYER = #{st_buyer_code}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{QUOTATION_SEQ}
       AND REVISION = #{st_revision}
       AND AGENT = #{AGENT}
       AND AGENT_REVISION = #{AGENT_REVISION}
       AND STATUS <> 'D'


	UPDATE KEPQTDT /*saveAllPmQTDT*/
       SET ATOB_UNIT_PRICE = #{ATOB_UNIT_PRICE}
       		, MIN_ORDER_QTY = DECODE(#{MIN_ORDER_QTY}, '', 1, #{MIN_ORDER_QTY})
			, PUR_UNIT_QTY = DECODE(#{PUR_UNIT_QTY}, '', 1, #{PUR_UNIT_QTY})
			, SELLER_AREA = #{SELLER_AREA}
     WHERE BUYER = #{st_buyer_code}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{QUOTATION_SEQ}
       AND REVISION = #{st_revision}
       AND AGENT = #{AGENT}
       AND AGENT_REVISION = #{AGENT_REVISION}
       AND STATUS <> 'D'
